<h1>المستخدمون</h1><table class="table bg-white"><tr><th>الاسم</th><th>البريد</th><th>الهاتف</th><th>الدور</th><th>نشط</th><th></th></tr><?php foreach($users as $u): ?><tr><form method="post" action="<?= url('/admin/users/save') ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $u['id'] ?>"><td><?= e($u['full_name']) ?></td><td><?= e($u['email']) ?></td><td><?= e($u['phone']) ?></td><td><select name="role" class="form-select form-select-sm"><?php foreach(['customer','manager','admin'] as $r): ?><option <?= $u['role']===$r?'selected':'' ?>><?= $r ?></option><?php endforeach; ?></select></td><td><input type="checkbox" name="is_active" <?= $u['is_active']?'checked':'' ?>></td><td><button class="btn btn-sm btn-primary">حفظ</button></td></form></tr><?php endforeach; ?></table>
